cd /home/user/money-maker/research/strategy_lab/fz_v3/out && ls ledger/ | head; echo; python3 - <<'EOF'
import glob, json, os
import pandas as pd
files = sorted(glob.glob('ledger/*'))
print('ledger files:', files)
rows=[]
for f in files:
    if f.endswith('.jsonl'):
        with open(f) as fh:
            for line in fh:
                line=line.strip()
                if line:
                    try: rows.append(json.loads(line))
                    except Exception as e: print('bad line', e)
    elif f.endswith('.csv'):
        try:
            df=pd.read_csv(f); print(f, df.shape, df.columns.tolist()[:20])
        except Exception as e: print(f, e)
    elif f.endswith('.parquet'):
        df=pd.read_parquet(f); print(f, df.shape, df.columns.tolist()[:20])
if rows:
    df=pd.DataFrame(rows)
    print(df.columns.tolist())
    fam=[c for c in df.columns if 'famil' in c]
    print('family col:', fam)
    col=fam[0] if fam else None
    if col:
        ss=df[df[col].astype(str).str.startswith('session_stop')]
        print('session_stop rows:', len(ss))
        print(ss[col].value_counts())
        if 'script' in ss.columns: print(ss['script'].value_counts())
EOF

